INSERT INTO public."levels" ("id", "level_code", "capability_id", "level_id", "title", "description", "observable_behavior", "example_outputs", "problem_statement", "duration_minutes", "difficulty_level", "status", "version_no", "is_active", "metadata")
VALUES ('8dfdd893-28c4-5650-a41c-06b31a9ace93'::uuid, 'RIV_L1', (SELECT "id" FROM public."capabilities" WHERE "code" = 'RIV-CAP-01'), (SELECT "id" FROM public."level_scale" WHERE "level_no" = 1), 'River Case Investigation', 'RAREMINDS River Mission — College Applied Learning. The team has complaints and a broad water-use claim, but needs a source-backed investigation and monitoring scope. Learner performs work from approved source records and stays within technical authority boundaries.', '["Classify reported water concerns, observations and unverified claims", "Identify affected stakeholder groups and their water uses", "Select monitoring sites for meaningful location comparisons"]'::jsonb, '["Case register", "stakeholder/site map", "monitoring proposal"]'::jsonb, '{"title": "River Case Investigation", "description": "The team has complaints and a broad water-use claim, but needs a source-backed investigation and monitoring scope."}'::jsonb, 45, 'beginner'::public.difficulty_level, 'published'::public.status, 1, TRUE, '{"source_document": "capability and roles.docx", "module_count": 4, "capability_codes": ["RIV-CAP-01", "RIV-CAP-02", "RIV-CAP-03"], "course": "RAREMINDS River Mission — College Applied Learning", "role_boundaries": "No unsupervised technical certification or spend authority", "duration_status": "not specified"}'::jsonb)
ON CONFLICT ("id") DO UPDATE SET "status" = EXCLUDED."status";
INSERT INTO public."levels" ("id", "level_code", "capability_id", "level_id", "title", "description", "observable_behavior", "example_outputs", "problem_statement", "duration_minutes", "difficulty_level", "status", "version_no", "is_active", "metadata")
VALUES ('91997bbd-7175-5ab8-8459-308d1f60ff95'::uuid, 'RIV_L2', (SELECT "id" FROM public."capabilities" WHERE "code" = 'RIV-CAP-04'), (SELECT "id" FROM public."level_scale" WHERE "level_no" = 2), 'Field, Sample Custody and Laboratory Evidence', 'RAREMINDS River Mission — College Applied Learning. The investigation must reconcile field and laboratory records while separating QC review from technical release. Learner performs work from approved source records and stays within technical authority boundaries.', '["Review documented sampling methods and authority to proceed", "Interpret pH, dissolved oxygen, BOD and microbial readings"]'::jsonb, '["Sample/custody register", "laboratory QC exception pack", "provisional evidence packet"]'::jsonb, '{"title": "Field, Sample Custody and Laboratory Evidence", "description": "The investigation must reconcile field and laboratory records while separating QC review from technical release."}'::jsonb, 45, 'foundation'::public.difficulty_level, 'published'::public.status, 1, TRUE, '{"source_document": "capability and roles.docx", "module_count": 3, "capability_codes": ["RIV-CAP-04", "RIV-CAP-05"], "course": "RAREMINDS River Mission — College Applied Learning", "role_boundaries": "No unsupervised technical certification or spend authority", "duration_status": "not specified"}'::jsonb)
ON CONFLICT ("id") DO UPDATE SET "status" = EXCLUDED."status";
