VALUES ('e81d667a-9e9f-51e3-a3f9-d850e490d5e0'::uuid, 'RIV_L3', (SELECT "id" FROM public."capabilities" WHERE "code" = 'RIV-CAP-06'), (SELECT "id" FROM public."level_scale" WHERE "level_no" = 3), 'Water Data Analysis and Qualified Findings', 'RAREMINDS River Mission — College Applied Learning. The case needs a joined, checked dataset, comparisons, hypothesis testing and method-limited interpretation. Learner performs work from approved source records and stays within technical authority boundaries.', '["Clean and join records using sample IDs, dates and units", "Form competing explanations for changing water evidence", "Identify potentially applicable water-use reference criteria"]'::jsonb, '["Analytical workbook", "chart and filters", "hypothesis matrix", "criteria comparison"]'::jsonb, '{"title": "Water Data Analysis and Qualified Findings", "description": "The case needs a joined, checked dataset, comparisons, hypothesis testing and method-limited interpretation."}'::jsonb, 45, 'intermediate'::public.difficulty_level, 'published'::public.status, 1, TRUE, '{"source_document": "capability and roles.docx", "module_count": 4, "capability_codes": ["RIV-CAP-06", "RIV-CAP-07", "RIV-CAP-08"], "course": "RAREMINDS River Mission — College Applied Learning", "role_boundaries": "No unsupervised technical certification or spend authority", "duration_status": "not specified"}'::jsonb)
