VALUES ('a2d5fe40-6dfa-5153-8615-12f7d9f2e222'::uuid, 'RIV_L4', (SELECT "id" FROM public."capabilities" WHERE "code" = 'RIV-CAP-09'), (SELECT "id" FROM public."level_scale" WHERE "level_no" = 4), 'Intervention Planning and Decision Controls', 'RAREMINDS River Mission — College Applied Learning. The investigation needs defensible options, costs, procurement boundaries and follow-up verification. Learner performs work from approved source records and stays within technical authority boundaries.', '["Compare monitoring, treatment and pollution-control alternatives", "Prepare work packages, owners, schedules and costs"]'::jsonb, '["Intervention evaluation", "project budget and authority records", "verification referral"]'::jsonb, '{"title": "Intervention Planning and Decision Controls", "description": "The investigation needs defensible options, costs, procurement boundaries and follow-up verification."}'::jsonb, 45, 'advanced'::public.difficulty_level, 'published'::public.status, 1, TRUE, '{"source_document": "capability and roles.docx", "module_count": 4, "capability_codes": ["RIV-CAP-09", "RIV-CAP-10"], "course": "RAREMINDS River Mission — College Applied Learning", "role_boundaries": "No unsupervised technical certification or spend authority", "duration_status": "not specified"}'::jsonb)
