VALUES ('705b92e1-63b5-5a2a-9272-a71b8dcd2948'::uuid, 'RIV_L5', (SELECT "id" FROM public."capabilities" WHERE "code" = 'RIV-CAP-11'), (SELECT "id" FROM public."level_scale" WHERE "level_no" = 5), 'Independent Water Investigation Transfer', 'RAREMINDS River Mission — College Applied Learning. An unfamiliar tributary case requires one selected role to produce a traceable professional work product. Learner performs work from approved source records and stays within technical authority boundaries.', '["Interpret an unfamiliar water-quality case in a selected role"]'::jsonb, '["Role-selected evidence portfolio", "independent reviewer handover"]'::jsonb, '{"title": "Independent Water Investigation Transfer", "description": "An unfamiliar tributary case requires one selected role to produce a traceable professional work product."}'::jsonb, 45, 'expert'::public.difficulty_level, 'published'::public.status, 1, TRUE, '{"source_document": "capability and roles.docx", "module_count": 2, "capability_codes": ["RIV-CAP-11"], "course": "RAREMINDS River Mission — College Applied Learning", "role_boundaries": "No unsupervised technical certification or spend authority", "duration_status": "not specified"}'::jsonb)
