INSERT INTO public."modules" ("id", "level_id", "module_no", "title", "description", "pressure_points", "user_confusion", "industry_challenge", "prerequisites", "what_youll_learn", "when_to_apply", "learning_content", "support", "knowledge", "module_problem_statement", "tools", "is_published", "is_active", "metadata")
VALUES ('eb6dd2a8-6a42-570d-8f0f-7f37f95d7ab5'::uuid, '8dfdd893-28c4-5650-a41c-06b31a9ace93'::uuid, 1, 'Open the Case and Challenge the Claim', 'A pH-only report is treated as evidence of universal water safety even though the supporting facts are incomplete. Learner completes T001–T005 to produce: Case intake and investigation brief; original complaint and report references.', '["Source gaps", "method limitations", "approval authority", "task-to-task handover"]'::jsonb, '["The learner may mistake a reported claim for a verified finding."]'::jsonb, 'Environmental water-quality investigation depends on traceable site, laboratory, analysis and authorised decision evidence.', '["River case input and original source document"]'::jsonb, '["Distinguish reported concerns from verified observations"]'::jsonb, 'Use when conducting the open the case and challenge the claim stage of a water-quality investigation.', '{"major_concepts": ["Module tasks T001–T005: source → working field → action/result → source check → saved handover; 6E Engage → Explore → Explain → Express → Empower → Evolve."]}'::jsonb, '{"ai_support_tips": "Case source documents|LMS foundation where necessary|learner task workbook"}'::jsonb, '{"technical_concepts_learnt": ["reported concern", "source fact", "unsupported claim", "open investigation question"]}'::jsonb, 'A pH-only report is treated as evidence of universal water safety even though the supporting facts are incomplete.', '{"items": ["Excel learner workbook", "PowerPoint 6E task decks"]}'::jsonb, TRUE, TRUE, '{"source_document": "capability and roles.docx", "course": "RAREMINDS River Mission — College Applied Learning", "task_ids": ["T001", "T002", "T003", "T004", "T005"], "capability_ids": ["RIV-CAP-01"], "source_drive_folder": "https://drive.google.com/drive/folders/1SFL4EDw1n5ThPOaOBA46cCpNaASQaXNL", "output": "Case intake and investigation brief; original complaint and report references", "resource_status": "connected Drive file", "technical_authority": "unverified; preserve HOLD"}'::jsonb)
ON CONFLICT ("id") DO UPDATE SET "is_published" = EXCLUDED."is_published";
INSERT INTO public."modules" ("id", "level_id", "module_no", "title", "description", "pressure_points", "user_confusion", "industry_challenge", "prerequisites", "what_youll_learn", "when_to_apply", "learning_content", "support", "knowledge", "module_problem_statement", "tools", "is_published", "is_active", "metadata")
VALUES ('6a10f8dc-f14b-598d-a9da-ea16afb4a9bb'::uuid, '8dfdd893-28c4-5650-a41c-06b31a9ace93'::uuid, 2, 'Understand People, Places and Timing', 'Affected groups, sites and event dates are not connected to the complaint evidence. Learner completes T006–T012 to produce: Stakeholder register, site-chainage schematic and dated evidence timeline.', '["Source gaps", "method limitations", "approval authority", "task-to-task handover"]'::jsonb, '["The learner may add overlapping population counts or assign a source without evidence."]'::jsonb, 'Environmental water-quality investigation depends on traceable site, laboratory, analysis and authorised decision evidence.', '["Verified previous module record and its outstanding evidence limitations"]'::jsonb, '["Identify affected groups, water uses and relevant site conditions"]'::jsonb, 'Use when conducting the understand people, places and timing stage of a water-quality investigation.', '{"major_concepts": ["Module tasks T006–T012: source → working field → action/result → source check → saved handover; 6E Engage → Explore → Explain → Express → Empower → Evolve."]}'::jsonb, '{"ai_support_tips": "Case source documents|LMS foundation where necessary|learner task workbook"}'::jsonb, '{"technical_concepts_learnt": ["stakeholder", "chainage", "date", "land use", "source ID"]}'::jsonb, 'Affected groups, sites and event dates are not connected to the complaint evidence.', '{"items": ["Excel learner workbook", "PowerPoint 6E task decks"]}'::jsonb, TRUE, TRUE, '{"source_document": "capability and roles.docx", "course": "RAREMINDS River Mission — College Applied Learning", "task_ids": ["T006", "T007", "T008", "T009", "T010", "T011", "T012"], "capability_ids": ["RIV-CAP-02"], "source_drive_folder": "https://drive.google.com/drive/folders/1waj9gqC2pcjmmHgsnZTQopPV3Hf00Uml", "output": "Stakeholder register, site-chainage schematic and dated evidence timeline", "resource_status": "connected Drive file", "technical_authority": "unverified; preserve HOLD"}'::jsonb)
ON CONFLICT ("id") DO UPDATE SET "is_published" = EXCLUDED."is_published";
INSERT INTO public."modules" ("id", "level_id", "module_no", "title", "description", "pressure_points", "user_confusion", "industry_challenge", "prerequisites", "what_youll_learn", "when_to_apply", "learning_content", "support", "knowledge", "module_problem_statement", "tools", "is_published", "is_active", "metadata")
VALUES ('d8ca1487-82a6-5ceb-8e02-efc9a4bf1ae9'::uuid, '8dfdd893-28c4-5650-a41c-06b31a9ace93'::uuid, 3, 'Design the Monitoring Plan', 'The investigation needs defensible station, parameter and schedule selections. Learner completes T013–T015 to produce: MON-01 station and parameter monitoring plan.', '["Source gaps", "method limitations", "approval authority", "task-to-task handover"]'::jsonb, '["The learner may select a measurement without checking what evidence gap it addresses."]'::jsonb, 'Environmental water-quality investigation depends on traceable site, laboratory, analysis and authorised decision evidence.', '["Verified previous module record and its outstanding evidence limitations"]'::jsonb, '["Select appropriate monitoring locations, parameters and records"]'::jsonb, 'Use when conducting the design the monitoring plan stage of a water-quality investigation.', '{"major_concepts": ["Module tasks T013–T015: source → working field → action/result → source check → saved handover; 6E Engage → Explore → Explain → Express → Empower → Evolve."]}'::jsonb, '{"ai_support_tips": "Case source documents|LMS foundation where necessary|learner task workbook"}'::jsonb, '{"technical_concepts_learnt": ["station", "parameter", "campaign", "method", "planned timing"]}'::jsonb, 'The investigation needs defensible station, parameter and schedule selections.', '{"items": ["Excel learner workbook", "PowerPoint 6E task decks"]}'::jsonb, TRUE, TRUE, '{"source_document": "capability and roles.docx", "course": "RAREMINDS River Mission — College Applied Learning", "task_ids": ["T013", "T014", "T015"], "capability_ids": ["RIV-CAP-03"], "source_drive_folder": "https://drive.google.com/drive/folders/1sNQ-8s_X9chRlXCp6RyqSqqIgfdOVuFP", "output": "MON-01 station and parameter monitoring plan", "resource_status": "connected Drive file", "technical_authority": "unverified; preserve HOLD"}'::jsonb)
ON CONFLICT ("id") DO UPDATE SET "is_published" = EXCLUDED."is_published";
