VALUES ('b04c4d31-09e9-53cb-a28c-f823a596ab58'::uuid, '8dfdd893-28c4-5650-a41c-06b31a9ace93'::uuid, 4, 'Gate the Work Before Field Release', 'Programme scope approval is available, but original method, calibration and physical release proof are missing. Learner completes T016–T018 to produce: Preflight technical HOLD, monitoring-scope disposition and escalation record.', '["Source gaps", "method limitations", "approval authority", "task-to-task handover"]'::jsonb, '["The learner may mistake an approved plan for permission to collect samples."]'::jsonb, 'Environmental water-quality investigation depends on traceable site, laboratory, analysis and authorised decision evidence.', '["Verified previous module record and its outstanding evidence limitations"]'::jsonb, '["Select appropriate monitoring locations, parameters and records", "Apply or correctly interpret documented sampling and testing procedures"]'::jsonb, 'Use when conducting the gate the work before field release stage of a water-quality investigation.', '{"major_concepts": ["Module tasks T016–T018: source → working field → action/result → source check → saved handover; 6E Engage → Explore → Explain → Express → Empower → Evolve."]}'::jsonb, '{"ai_support_tips": "Case source documents|LMS foundation where necessary|learner task workbook"}'::jsonb, '{"technical_concepts_learnt": ["scope decision", "SOP", "calibration", "technical release", "escalation"]}'::jsonb, 'Programme scope approval is available, but original method, calibration and physical release proof are missing.', '{"items": ["Excel learner workbook", "PowerPoint 6E task decks"]}'::jsonb, TRUE, TRUE, '{"source_document": "capability and roles.docx", "course": "RAREMINDS River Mission — College Applied Learning", "task_ids": ["T016", "T017", "T018"], "capability_ids": ["RIV-CAP-03", "RIV-CAP-04"], "source_drive_folder": "https://drive.google.com/drive/folders/1RKgW0BQa6P-KoNolIsIF3wxvYtJgtvhq", "output": "Preflight technical HOLD, monitoring-scope disposition and escalation record", "resource_status": "connected Drive file", "technical_authority": "unverified; preserve HOLD"}'::jsonb)
ON CONFLICT ("id") DO UPDATE SET "is_published" = EXCLUDED."is_published";
