VALUES ('1714a434-dccd-57d9-bb40-38dee5fa0f1d'::uuid, '91997bbd-7175-5ab8-8459-308d1f60ff95'::uuid, 1, 'Review Readiness and Sample Custody', 'Field and sample records exist but must be reconciled against their station, seal, collector and custody evidence. Learner completes T019–T024 to produce: Readiness checklist, source-backed field log and custody register.', '["Source gaps", "method limitations", "approval authority", "task-to-task handover"]'::jsonb, '["The learner may transfer an exclusion decision to the wrong sample."]'::jsonb, 'Environmental water-quality investigation depends on traceable site, laboratory, analysis and authorised decision evidence.', '["Verified previous module record and its outstanding evidence limitations"]'::jsonb, '["Apply or correctly interpret documented sampling and testing procedures"]'::jsonb, 'Use when conducting the review readiness and sample custody stage of a water-quality investigation.', '{"major_concepts": ["Module tasks T019–T024: source → working field → action/result → source check → saved handover; 6E Engage → Explore → Explain → Express → Empower → Evolve."]}'::jsonb, '{"ai_support_tips": "Case source documents|LMS foundation where necessary|learner task workbook"}'::jsonb, '{"technical_concepts_learnt": ["instrument", "sample ID", "station", "seal", "custody", "timestamp"]}'::jsonb, 'Field and sample records exist but must be reconciled against their station, seal, collector and custody evidence.', '{"items": ["Excel learner workbook", "PowerPoint 6E task decks"]}'::jsonb, TRUE, TRUE, '{"source_document": "capability and roles.docx", "course": "RAREMINDS River Mission — College Applied Learning", "task_ids": ["T019", "T020", "T021", "T022", "T023", "T024"], "capability_ids": ["RIV-CAP-04"], "source_drive_folder": "https://drive.google.com/drive/folders/1JfFiosbgbtKvgj7JJ1OgvMqHIwvn7Rml", "output": "Readiness checklist, source-backed field log and custody register", "resource_status": "connected Drive file", "techn