VALUES ('da1d995c-0ea8-5f6e-9683-b984547ad433'::uuid, '705b92e1-63b5-5a2a-9272-a71b8dcd2948'::uuid, 2, 'Deliver Your Independent Professional Handover', 'The learner must submit a professional role-specific output from incomplete unfamiliar evidence. Learner completes T070–T072 to produce: One independent portfolio, source register and reviewer handover.', '["Source gaps", "method limitations", "approval authority", "task-to-task handover"]'::jsonb, '["The learner may manufacture a missing reading or self-award professional approval."]'::jsonb, 'Environmental water-quality investigation depends on traceable site, laboratory, analysis and authorised decision evidence.', '["Verified previous module record and its outstanding evidence limitations"]'::jsonb, '["Apply the complete investigation process to an unfamiliar water-quality case"]'::jsonb, 'Use when conducting the deliver your independent professional handover stage of a water-quality investigation.', '{"major_concepts": ["Module tasks T070–T072: source → working field → action/result → source check → saved handover; 6E Engage → Explore → Explain → Express → Empower → Evolve."]}'::jsonb, '{"ai_support_tips": "Case source documents|LMS foundation where necessary|learner task workbook"}'::jsonb, '{"technical_concepts_learnt": ["role-specific work", "evidence", "exception", "reviewer", "handover"]}'::jsonb, 'The learner must submit a professional role-specific output from incomplete unfamiliar evidence.', '{"items": ["Excel learner workbook", "PowerPoint 6E task decks"]}'::jsonb, TRUE, TRUE, '{"source_document": "capability and roles.docx", "course": "RAREMINDS River Mission — College Applied Learning", "task_ids": ["T070", "T071", "T072"], "capability_ids": ["RIV-CAP-11"], "source_drive_folder": "https://drive.google.com/drive/folders/11u3tUa3WKhWZXD_Q5aWSfkBxpBto8py0", "output": "One independent portfolio, source register and reviewer handover", "resource_status": "connected Drive file", "technical_authority": "unverified; preserve HOLD"}'::jsonb)
